#!/usr/bin/env python3
"""Generate k8s/es4/policy/workload-whitelist-admission.yaml from k8s/es4/policy/allowed-workloads.

  render-workload-whitelist-policy.py          write the file
  render-workload-whitelist-policy.py --stdout [--action Warn,Audit]   print it (rollout: Warn+Audit first)
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
LIST = ROOT / "k8s/es4/policy/allowed-workloads"
OUT = ROOT / "k8s/es4/policy/workload-whitelist-admission.yaml"

HEADER = """\
# GENERATED by scripts/es4/render-workload-whitelist-policy.py from k8s/es4/policy/allowed-workloads - DO NOT EDIT.
#
# es4 WORKLOAD WHITELIST (owner 2026-11-02: "only whitelist services get deployed there on
# kubernetes"). Denies CREATE/UPDATE of any top-level workload in namespace options-edge whose name is
# not in the allowlist: Deployment, StatefulSet, DaemonSet, CronJob, Job, and bare Pods.
# Pods and Jobs that carry an ownerReference (ReplicaSet/StatefulSet/DaemonSet/CronJob children) are
# passed so allowed controllers keep rolling; the allowed Deployment/StatefulSet/DaemonSet/CronJob
# itself is what is name-checked. DELETE and scale are never gated (so a removed service can always
# be taken down). Scoped by namespace name, not by an opt-in label, so it cannot be left disarmed.
# Admission runs after authorization: system:masters is NOT exempt. Independent of, and additive to,
# options-edge-jenkins-only-workloads.
# Apply (cluster-scoped, needs admin): bootstrap-es4.sh does it; by hand:
#   kubectl --kubeconfig ~/.kube/es4.kubeconfig apply -f k8s/es4/policy/workload-whitelist-admission.yaml
"""


def names():
    out = [l.strip() for l in LIST.read_text().splitlines() if l.strip() and not l.lstrip().startswith("#")]
    if not out or len(set(out)) != len(out):
        sys.exit("allowed-workloads is empty or has duplicates")
    return sorted(out)


def render(actions=("Deny",)):
    cel = "[" + ", ".join(f"'{n}'" for n in names()) + "]"
    acts = "\n".join(f"    - {a}" for a in actions)
    return HEADER + f"""\
apiVersion: admissionregistration.k8s.io/v1
kind: ValidatingAdmissionPolicy
metadata:
  name: options-edge-es4-workload-whitelist
spec:
  failurePolicy: Fail
  matchConstraints:
    resourceRules:
      - apiGroups: ["apps"]
        apiVersions: ["v1"]
        operations: ["CREATE", "UPDATE"]
        resources: ["deployments", "statefulsets", "daemonsets"]
      - apiGroups: ["batch"]
        apiVersions: ["v1"]
        operations: ["CREATE", "UPDATE"]
        resources: ["cronjobs", "jobs"]
      - apiGroups: [""]
        apiVersions: ["v1"]
        operations: ["CREATE"]
        resources: ["pods"]
  variables:
    - name: wname
      expression: "object.metadata.?name.orValue(object.metadata.?generateName.orValue(''))"
  validations:
    - expression: >-
        variables.wname in {cel}
        || ((request.resource.resource == 'pods' || request.resource.resource == 'jobs')
            && object.metadata.?ownerReferences.orValue([]).exists(o, o.kind in ['ReplicaSet', 'StatefulSet', 'DaemonSet', 'Job', 'CronJob']))
      messageExpression: >-
        'Workload ' + variables.wname + ' (' + request.resource.resource + ') is not on the es4 whitelist: only ES-related services may run on es4 (k8s/es4/policy/allowed-workloads).'
---
apiVersion: admissionregistration.k8s.io/v1
kind: ValidatingAdmissionPolicyBinding
metadata:
  name: options-edge-es4-workload-whitelist
spec:
  policyName: options-edge-es4-workload-whitelist
  validationActions:
{acts}
  matchResources:
    namespaceSelector:
      matchLabels:
        kubernetes.io/metadata.name: options-edge
"""


if __name__ == "__main__":
    if "--stdout" in sys.argv:
        a = ("Deny",)
        if "--action" in sys.argv:
            a = tuple(sys.argv[sys.argv.index("--action") + 1].split(","))
        sys.stdout.write(render(a))
    else:
        OUT.write_text(render())
